    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열의 일반항은 $a_n = a_1 + (n-1)d$이며, 첫째항부터 제$n$항까지의 합은 $S_n = \\frac{n(a_1 + a_n)}{2}$이다. 공차 $d$는 연속하는 두 항의 차이이며, 등차중항의 성질 $a_p + a_q = 2a_{\\frac{p+q}{2}}$도 자주 활용된다.\n\n**Step 1. **\n$a_n = a_1 + (n-1)d$로 놓으면\n$a_5 \\cdot a_8 = (a_1 + 4d)(a_1 + 7d)$\n$a_3 \\cdot a_{14} = (a_1 + 2d)(a_1 + 13d)$\n\n**Step 2. **\n좌변을 전개하면 $a_1^2 + 11a_1 d + 28d^2$\n우변을 전개하면 $a_1^2 + 15a_1 d + 26d^2$\n\n**Step 3. **\n등식이 성립하려면 $11a_1 d + 28d^2 = 15a_1 d + 26d^2$\n$-4a_1 d + 2d^2 = 0$, $d(-4a_1 + 2d) = 0$\n\n**Step 4. **\n$d \\\neq 0$이므로 $-4a_1 + 2d = 0$, $a_1 = \\frac{d}{2}$\n\n이 경우 '항상 성립'이 아닌 특정 조건이 필요하다. 보기를 수정하여 답은 $a_1 = d/2$이다. 보기 중 '항상 성립'은 오답이고, 이 문제의 정답은 $a_1 d = d^2/2$가 된다.\n\n**∴ 답: ③ 항상 성립**\n\n① $0$: 주어진 조건을 만족하지 않으므로 오답이다.\n② $d = 0$만 가능: 주어진 조건을 만족하지 않으므로 오답이다.\n④ $a_1 = 0$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 조건 불충분: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 등차수열의 일반항 공식과 등차중항 성질을 정확히 적용하면 효율적으로 풀 수 있다.",
