    "answer": 4,
    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열의 일반항은 $a_n = a_1 + (n-1)d$이며, 첫째항부터 제$n$항까지의 합은 $S_n = \\frac{n(a_1 + a_n)}{2}$이다. 공차 $d$는 연속하는 두 항의 차이이며, 등차중항의 성질 $a_p + a_q = 2a_{\\frac{p+q}{2}}$도 자주 활용된다.\n\n**Step 1. **\n$S_{2n-1} = (2n-1)(n+3)$에서 $S_{2n-1} = (2n-1) \\cdot a_n$ (등차수열의 성질)\n\n**Step 2. **\n$a_n^2 - a_{n-1} \\cdot a_{n+1}$\n$= (n+3)^2 - (n+2)(n+4)$\n$= n^2 + 6n + 9 - (n^2 + 6n + 8)$\n$= 1$\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 4**\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**주의사항:** 계산 실수를 방지하기 위해 중간 과정을 꼼꼼히 확인하고, 최종 답을 반드시 검증한다.\n\n**참고:** 이 유형의 문제는 수능에서 자주 출제되며, 기본 공식을 정확히 외우고 있으면 빠르게 풀 수 있다. 중간 계산 과정을 생략하지 말고 꼼꼼히 기록하는 것이 실수를 줄이는 핵심이다.\n\n**💡 포인트:** 등차수열의 일반항 공식과 등차중항 성질을 정확히 적용하면 효율적으로 풀 수 있다.",
