    "explanation": "**[풀이]**\n\n**기본 개념:** 등비수열의 일반항은 $a_n = a_1 \\cdot r^{n-1}$이며, 첫째항부터 제$n$항까지의 합은 $S_n = \\frac{a_1(r^n - 1)}{r - 1}$ ($r \\\neq 1$)이다. 등비중항의 성질 $a_n^2 = a_{n-1} \\cdot a_{n+1}$과 공비 $r$의 부호·절댓값이 핵심이다.\n\n**Step 1. **\n$a_2 a_4 = a_3^2$ (등비중항)\n또한 $a_1 a_5 = a_3^2$ (등비중항)\n\n**Step 2. **\n$a_2 + a_4 = 20$이고 $a_2 a_4 = a_3^2$이므로\n$a_2, a_4$는 $t^2 - 20t + a_3^2 = 0$의 근이다.\n\n**Step 3. **\n마찬가지로 $a_1 + a_5 = 34$, $a_1 a_5 = a_3^2$\n\n**Step 4. **\n$a_1 = \\frac{a_2}{r}$, $a_5 = a_4 \\cdot r$이므로\n$a_1 + a_5 = \\frac{a_2}{r} + a_4 r$\n\n$a_2 + a_4 = 20$, $a_1 + a_5 = 34$에서\n$\\frac{a_2 + a_4 r^2}{r} = 34$가 아닌...\n\n다른 접근: $a_1 + a_5 = a_3(r^{-2} + r^2) = 34$, $a_2 + a_4 = a_3(r^{-1} + r) = 20$\n\n$r + \\frac{1}{r} = t$로 놓으면 $r^2 + \\frac{1}{r^2} = t^2 - 2$\n\n$a_3 t = 20$, $a_3(t^2 - 2) = 34$\n\n$\\frac{t^2 - 2}{t} = \\frac{34}{20} = \\frac{17}{10}$\n\n$10t^2 - 20 = 17t$, $10t^2 - 17t - 20 = 0$\n\n$t = \\frac{17 \\\\pm \\sqrt{289 + 800}}{20} = \\frac{17 \\\\pm \\sqrt{1089}}{20} = \\frac{17 \\\\pm 33}{20}$\n\n$t = \\frac{50}{20} = \\frac{5}{2}$ (양수 택)\n\n$a_3 = \\frac{20}{5/2} = 8$\n\n**∴ 답: ② $8$**\n\n① $6$: 주어진 조건을 만족하지 않으므로 오답이다.\n③ $10$: 주어진 조건을 만족하지 않으므로 오답이다.\n④ $12$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ $16$: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 등비수열에서 공비의 부호와 절댓값에 주의하고, 등비중항 성질을 적극 활용한다.",
