    "explanation": "**[풀이]**\n\n**기본 개념:** 등비수열의 일반항은 $a_n = a_1 \\cdot r^{n-1}$이며, 첫째항부터 제$n$항까지의 합은 $S_n = \\frac{a_1(r^n - 1)}{r - 1}$ ($r \\\neq 1$)이다. 등비중항의 성질 $a_n^2 = a_{n-1} \\cdot a_{n+1}$과 공비 $r$의 부호·절댓값이 핵심이다.\n\n**Step 1. **\n$a_2 - a_1 = a_1(r - 1) = 1$\n$a_4 - a_3 = a_3(r - 1) = a_1 r^2(r - 1) = 4$\n\n**Step 2. **\n$\\frac{a_4 - a_3}{a_2 - a_1} = r^2 = 4$, $r = 2$\n\n**Step 3. **\n$a_1(2 - 1) = 1$이므로 $a_1 = 1$\n\n**Step 4. **\n$a_5 = 1 \\cdot 2^4 = 16$\n\n**∴ 답: ④ $32$**\n\n① $8$: 주어진 조건을 만족하지 않으므로 오답이다.\n② $16$: 주어진 조건을 만족하지 않으므로 오답이다.\n③ $24$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ $48$: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**💡 포인트:** 등비수열에서 공비의 부호와 절댓값에 주의하고, 등비중항 성질을 적극 활용한다.",
