    "explanation": "**[풀이]**\n\n**기본 개념:** 수열의 합 $S_n$에서 일반항은 $a_n = S_n - S_{n-1}$ ($n \\geq 2$)로 구한다. 자연수 합 $\\sum k = \\frac{n(n+1)}{2}$, 제곱합 $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, 부분분수 분해, 망원급수(텔레스코핑)가 핵심 도구이다.\n\n**Step 1. **\n$\\sum_{k=1}^{10} (3k + 1) = 3\\sum_{k=1}^{10} k + \\sum_{k=1}^{10} 1$\n\n**Step 2. **\n$= 3 \\cdot \\frac{10 \\cdot 11}{2} + 10 = 3 \\cdot 55 + 10 = 165 + 10 = 175$\n\n**Step 3. 검산**\n위 계산 과정을 대입하여 조건이 만족되는지 확인한다.\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 175**\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**주의사항:** 계산 실수를 방지하기 위해 중간 과정을 꼼꼼히 확인하고, 최종 답을 반드시 검증한다.\n\n**💡 포인트:** 시그마 공식, 부분분수 분해, 망원급수 등 상황에 맞는 테크닉을 선택한다.",
