    "explanation": "**[풀이]**\n\n**기본 개념:** 수열의 합 $S_n$에서 일반항은 $a_n = S_n - S_{n-1}$ ($n \\geq 2$)로 구한다. 자연수 합 $\\sum k = \\frac{n(n+1)}{2}$, 제곱합 $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, 부분분수 분해, 망원급수(텔레스코핑)가 핵심 도구이다.\n\n**Step 1. **\n공식: $\\sum_{k=1}^{n} k x^k = \\frac{x(1 - (n+1)x^n + nx^{n+1})}{(1-x)^2}$\n\n$x = 2$일 때: $S = \\sum_{k=1}^{10} k \\cdot 2^k$\n\n**Step 2. **\n$S = 2 + 2 \\cdot 4 + 3 \\cdot 8 + 4 \\cdot 16 + 5 \\cdot 32 + 6 \\cdot 64 + 7 \\cdot 128 + 8 \\cdot 256 + 9 \\cdot 512 + 10 \\cdot 1024$\n\n**Step 3. **\n$= 2 + 8 + 24 + 64 + 160 + 384 + 896 + 2048 + 4608 + 10240 = 18434$\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 18434**\n\n**💡 포인트:** 시그마 공식, 부분분수 분해, 망원급수 등 상황에 맞는 테크닉을 선택한다.",
