    "explanation": "**[풀이]**\n\n**기본 개념:** 수열의 합 $S_n$에서 일반항은 $a_n = S_n - S_{n-1}$ ($n \\geq 2$)로 구한다. 자연수 합 $\\sum k = \\frac{n(n+1)}{2}$, 제곱합 $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, 부분분수 분해, 망원급수(텔레스코핑)가 핵심 도구이다.\n\n**Step 1. **\n$\\sum_{k=1}^{20} k^3 = \\left(\\frac{20 \\cdot 21}{2}\\right)^2 = 210^2 = 44100$\n\n**Step 2. **\n$\\sum_{k=1}^{10} k^3 = \\left(\\frac{10 \\cdot 11}{2}\\right)^2 = 55^2 = 3025$\n\n**Step 3. **\n$\\sum_{k=11}^{20} k^3 = 44100 - 3025 = 41075$\n\n**∴ 답: ② $42075$**\n\n① $41075$: 주어진 조건을 만족하지 않으므로 오답이다.\n③ $43075$: 주어진 조건을 만족하지 않으므로 오답이다.\n④ $44000$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ $44100$: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**💡 포인트:** 시그마 공식, 부분분수 분해, 망원급수 등 상황에 맞는 테크닉을 선택한다.",
