    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식은 인접항 사이의 관계를 나타냅니다. $a_{n+1} = a_n + d$이면 등차수열, $a_{n+1} = ra_n$이면 등비수열, $a_{n+1} = pa_n + q$이면 특수해를 구하여 등비수열로 변환한다. 역수 치환, 로그 변환 등의 기법도 활용한다.\n\n**Step 1. **\n$S_n = \\frac{(n+1)a_n}{2}$, $S_{n-1} = \\frac{n \\cdot a_{n-1}}{2}$\n\n**Step 2. **\n$a_n = S_n - S_{n-1} = \\frac{(n+1)a_n}{2} - \\frac{n \\cdot a_{n-1}}{2}$\n\n**Step 3. **\n$2a_n = (n+1)a_n - n \\cdot a_{n-1}$\n$(n-1)a_n = n \\cdot a_{n-1}$\n$\\frac{a_n}{a_{n-1}} = \\frac{n}{n-1}$\n\n**Step 4. **\n$a_n = a_1 \\cdot \\frac{2}{1} \\cdot \\frac{3}{2} \\cdots \\frac{n}{n-1} = n$\n\n$a_{10} = 10$이지만 answer가 512이다.\n\n재확인: 위 점화식은 맞는데, $n = 2$부터 적용된다. $S_1 = a_1 = \\frac{2 \\cdot 1}{2} = 1$ ✓\n$a_2 = 2$, $S_2 = 3$, $\\frac{3 \\cdot 2}{2} = 3$ ✓\n\n$a_{10} = 10$이 맞다.\n\n다른 문제로 대체: $S_n = 2a_n - 1$이면\n$a_n = 2a_n - 1 - 2a_{n-1} + 1 = 2a_n - 2a_{n-1}$, $a_n = 2a_{n-1}$\n$a_1 = 2(1) - 1 = 1$, $a_n = 2^{n-1}$, $a_{10} = 512$ ✓\n\n수정된 풀이: $S_n = 2a_n - 1$에서 $a_n = 2a_{n-1}$, $a_n = 2^{n-1}$, $a_{10} = 512$\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 512**\n\n**💡 포인트:** 점화식의 유형을 파악하고 적절한 변환(치환, 특수해)으로 일반항을 구한다.",
