    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식은 인접항 사이의 관계를 나타냅니다. $a_{n+1} = a_n + d$이면 등차수열, $a_{n+1} = ra_n$이면 등비수열, $a_{n+1} = pa_n + q$이면 특수해를 구하여 등비수열로 변환한다. 역수 치환, 로그 변환 등의 기법도 활용한다.\n\n**Step 1. **\n특수해를 $a_n = \\\\alpha n + \\\\beta$로 놓으면\n$\\\\alpha(n+1) + \\\\beta = 2(\\\\alpha n + \\\\beta) - n + 1$\n$\\\\alpha n + \\\\alpha + \\\\beta = 2\\\\alpha n + 2\\\\beta - n + 1$\n\n**Step 2. **\n계수 비교:\n$n$: $\\\\alpha = 2\\\\alpha - 1$, $\\\\alpha = 1$\n상수: $\\\\alpha + \\\\beta = 2\\\\beta + 1$, $1 + \\\\beta = 2\\\\beta + 1$, $\\\\beta = 0$\n\n특수해: $a_n = n$\n\n**Step 3. **\n제차해: $a_n = C \\cdot 2^n$\n\n일반해: $a_n = C \\cdot 2^n + n$\n\n**Step 4. **\n$a_1 = 2C + 1 = 3$에서 $C = 1$\n\n**Step 5. **\n$a_n = 2^n + n$\n\n검증: $a_1 = 2 + 1 = 3$ ✓, $a_2 = 4 + 2 = 6 = 2(3) - 1 + 1 = 6$ ✓\n\n**∴ 답: ② $2^n + n$**\n\n① $2^n + n - 1$: 주어진 조건을 만족하지 않으므로 오답이다.\n③ $2^n + n + 1$: 주어진 조건을 만족하지 않으므로 오답이다.\n④ $2^{n+1} + n$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ $2^{n-1} + n + 1$: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 점화식의 유형을 파악하고 적절한 변환(치환, 특수해)으로 일반항을 구한다.",
