    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식은 인접항 사이의 관계를 나타냅니다. $a_{n+1} = a_n + d$이면 등차수열, $a_{n+1} = ra_n$이면 등비수열, $a_{n+1} = pa_n + q$이면 특수해를 구하여 등비수열로 변환한다. 역수 치환, 로그 변환 등의 기법도 활용한다.\n\n**Step 1. **\n$\\lim_{n \\\\to \\infty} a_n = L$이라 하면 $L = \\frac{3L + 1}{L + 3}$\n\n**Step 2. **\n$L(L + 3) = 3L + 1$, $L^2 + 3L = 3L + 1$, $L^2 = 1$\n\n**Step 3. **\n$L = 1$ 또는 $L = -1$\n\n**Step 4. **\n$a_1 = 1 > 0$이고 점화식에서 양수이면 양수를 유지하므로 $L = 1$\n\n검증: $a_1 = 1$, $a_2 = \\frac{4}{4} = 1$이므로 모든 항이 1이다.\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 1**\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**주의사항:** 계산 실수를 방지하기 위해 중간 과정을 꼼꼼히 확인하고, 최종 답을 반드시 검증한다.\n\n**💡 포인트:** 점화식의 유형을 파악하고 적절한 변환(치환, 특수해)으로 일반항을 구한다.",
