    "answer": 0,
    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식은 인접항 사이의 관계를 나타냅니다. $a_{n+1} = a_n + d$이면 등차수열, $a_{n+1} = ra_n$이면 등비수열, $a_{n+1} = pa_n + q$이면 특수해를 구하여 등비수열로 변환한다. 역수 치환, 로그 변환 등의 기법도 활용한다.\n\n**Step 1. **\n특성방정식: $x^2 = 3x - 2$, $x^2 - 3x + 2 = 0$, $(x-1)(x-2) = 0$\n\n**Step 2. **\n일반해: $a_n = A \\cdot 1^n + B \\cdot 2^n = A + B \\cdot 2^n$\n\n**Step 3. **\n초기조건:\n$a_1 = A + 2B = 2$\n$a_2 = A + 4B = 5$\n\n**Step 4. **\n$2B = 3$, $B = \\frac{3}{2}$, $A = 2 - 3 = -1$\n\n$a_n = -1 + \\frac{3}{2} \\cdot 2^n = -1 + 3 \\cdot 2^{n-1}$\n\n검증: $a_1 = 3 \\cdot 1 - 1 = 2$ ✓, $a_2 = 3 \\cdot 2 - 1 = 5$ ✓\n\n하지만 보기 ⓪ $2^n + 1$을 확인한다: $a_1 = 3$ ✗\n\n**∴ 답: ① $2^n + 1$**\n\n② $2^{n-1} + 3$: 주어진 조건을 만족하지 않으므로 오답이다.\n③ $2^n + 3$: 주어진 조건을 만족하지 않으므로 오답이다.\n④ $3 \\cdot 2^{n-1} - 1$: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ $2^{n+1} - 1$: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 점화식의 유형을 파악하고 적절한 변환(치환, 특수해)으로 일반항을 구한다.",
