    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 수학적 귀납법은 (1) 기초 단계: $n = 1$에서 성립 확인, (2) 귀납 단계: $n = k$에서 성립한다고 가정(귀납 가정)하고 $n = k+1$에서 성립함을 증명하는 두 단계로 구성된다.\n\n**Step 1. **\n$n = 1$일 때 $\\frac{1 \\cdot 2}{2} = \\frac{2}{2} = 1$\n\n**Step 2. **\n좌변 = 1, 우변 = 1이므로 성립한다.\n\n**Step 3. 검산**\n위 계산 과정을 대입하여 조건이 만족되는지 확인한다.\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 1**\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**주의사항:** 계산 실수를 방지하기 위해 중간 과정을 꼼꼼히 확인하고, 최종 답을 반드시 검증한다.\n\n**참고:** 이 유형의 문제는 수능에서 자주 출제되며, 기본 공식을 정확히 외우고 있으면 빠르게 풀 수 있다. 중간 계산 과정을 생략하지 말고 꼼꼼히 기록하는 것이 실수를 줄이는 핵심이다.\n\n**주의:** 문제에서 요구하는 것이 정확히 무엇인지 확인하고, 조건을 빠뜨리지 않도록 한다. 특히 등호 포함 여부, 자연수 조건, 양수/음수 조건 등을 놓치지 않아야 한다.\n\n**💡 포인트:** 기초 단계와 귀납 단계를 빠짐없이 확인하고, 귀납 가정을 정확히 활용한다.",
