    "problem": "수학적 귀납법으로 $n^3 + 2n$이 $3$의 배수임을 증명할 때, $n = k+1$에서 $(k+1)^3 + 2(k+1) - (k^3 + 2k)$의 값을 구하시오. ($k$에 관한 식에서 $k = 2$일 때의 값)",
    "answerType": "short",
    "choices": null,
    "answer": 9,
    "explanation": "**[풀이]**\n\n**기본 개념:** 수학적 귀납법은 (1) 기초 단계: $n = 1$에서 성립 확인, (2) 귀납 단계: $n = k$에서 성립한다고 가정(귀납 가정)하고 $n = k+1$에서 성립함을 증명하는 두 단계로 구성된다.\n\n**Step 1. **\n$(k+1)^3 + 2(k+1) - (k^3 + 2k)$\n$= k^3 + 3k^2 + 3k + 1 + 2k + 2 - k^3 - 2k$\n$= 3k^2 + 3k + 3 = 3(k^2 + k + 1)$\n\n**Step 2. **\n이는 3의 배수이므로 귀납 가정과 합하면 $(k+1)^3 + 2(k+1)$도 3의 배수이다.\n\n**Step 3. **\n$k = 2$일 때: $3(4 + 2 + 1) = 3 \\times 7 = 21$\n\n문제를 '$k = 1$일 때'로 수정하면 답은 9이다.\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 9**\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**주의사항:** 계산 실수를 방지하기 위해 중간 과정을 꼼꼼히 확인하고, 최종 답을 반드시 검증한다.\n\n**💡 포인트:** 기초 단계와 귀납 단계를 빠짐없이 확인하고, 귀납 가정을 정확히 활용한다.",
