    "explanation": "**[풀이]**\n\n**기본 개념:** 시그마($\\sum$)의 기본 성질로 선형성 $\\sum(af(k)+b) = a\\sum f(k) + nb$, 합 공식 $\\sum k = \\frac{n(n+1)}{2}$, $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, $\\sum k^3 = \\left(\\frac{n(n+1)}{2}\\right)^2$을 사용한다.\n\n**Step 1. **\n부분분수 분해\n$$\\frac{1}{(3k-2)(3k+1)} = \\frac{1}{3}\\left(\\frac{1}{3k-2}-\\frac{1}{3k+1}\\right)$$\n\n**Step 2. **\n텔레스코핑\n$$\\frac{1}{3}\\sum_{k=1}^{n}\\left(\\frac{1}{3k-2}-\\frac{1}{3k+1}\\right) = \\frac{1}{3}\\left(1-\\frac{1}{3n+1}\\right) = \\frac{1}{3}\\cdot\\frac{3n}{3n+1} = \\frac{n}{3n+1}$$\n\n**Step 3. **\n방정식 풀기\n$$\\frac{n}{3n+1} = \\frac{5}{16}$$\n$$16n = 5(3n+1) = 15n+5$$\n$$n = 5$$\n\n**Step 4. 검산**\n$n=5$: $\\frac{5}{3 \\times 5+1} = \\frac{5}{16}$ ✓\n\n**∴ 답: 5**\n\n**💡 포인트:** 부분분수 분해와 텔레스코핑을 이용하면 합을 닫힌 형태로 구한다.",
