    "problem": "$f(x) = x^2+x$일 때, $\\displaystyle\\sum_{k=1}^{n}\\{f(k)-f(k-1)\\}$의 값은?\n\n① $n^2$\n② $n^2+n$\n③ $n^2-n$\n④ $n^2+2n$\n⑤ $2n^2+n$",
