    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 시그마($\\sum$)의 기본 성질로 선형성 $\\sum(af(k)+b) = a\\sum f(k) + nb$, 합 공식 $\\sum k = \\frac{n(n+1)}{2}$, $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$, $\\sum k^3 = \\left(\\frac{n(n+1)}{2}\\right)^2$을 사용한다.\n\n**Step 1. **\n텔레스코핑 적용\n$$\\sum_{k=1}^{n}\\{f(k)-f(k-1)\\} = f(n)-f(0)$$\n\n**Step 2. **\n계산\n$$f(n) = n^2+n, \\quad f(0) = 0$$\n$$f(n)-f(0) = n^2+n$$\n\n**Step 3. **\n검증: $n=3$일 때\n$f(1)-f(0)+f(2)-f(1)+f(3)-f(2) = f(3)-f(0) = 12-0 = 12$\n$n^2+n = 9+3 = 12$ ✓\n\n**∴ 답: ② $n^2+n$**\n\n**💡 포인트:** $\\sum\\{f(k)-f(k-1)\\}$은 항상 $f(n)-f(0)$으로 소거된다. 이것이 텔레스코핑의 핵심이다.\n\n**∴ 답: ② n²+n**\n\n① n²: 주어진 조건을 만족하지 않으므로 오답이다.\n③ n²-n: 주어진 조건을 만족하지 않으므로 오답이다.\n④ n²+2n: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 2n²+n: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 시그마의 선형성을 이용한 분리와 합 공식 적용을 정확히 수행한다.",
