    "explanation": "**[풀이]**\n\n**기본 개념:** 무한급수 $\\sum_{n=1}^{\\infty} a_n$의 합은 부분합의 극한 $\\lim_{n \\\\to \\infty} S_n$이다. 등비급수는 $|r| < 1$일 때 수렴하며 합은 $\\frac{a}{1-r}$이다. 수렴의 필요조건: $\\lim a_n = 0$.\n\n**Step 1. **\n부분분수 분해\n$$\\frac{1}{n(n+1)} = \\frac{1}{n}-\\frac{1}{n+1}$$\n\n**Step 2. **\n부분합 $S_n$ 구하기\n$$S_n = \\sum_{k=1}^{n}\\left(\\frac{1}{k}-\\frac{1}{k+1}\\right) = 1-\\frac{1}{n+1} = \\frac{n}{n+1}$$\n\n**Step 3. **\n극한값\n$$\\lim_{n\\to\\infty} S_n = \\lim_{n\\to\\infty}\\frac{n}{n+1} = 1$$\n\n**검증:** $S_1=\\frac{1}{2}$, $S_2=\\frac{2}{3}$, $S_3=\\frac{3}{4}$ → 1에 수렴 ✓\n\n**∴ 답: 1**\n\n**💡 포인트:** 무한급수의 합은 부분합의 극한값이다. 텔레스코핑 급수는 부분합을 쉽게 구한다.\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 1**\n\n**💡 포인트:** 부분합의 극한을 구하거나, 등비급수의 수렴 조건을 활용한다.",
