    "explanation": "**[풀이]**\n\n**기본 개념:** 무한급수 $\\sum_{n=1}^{\\infty} a_n$의 합은 부분합의 극한 $\\lim_{n \\\\to \\infty} S_n$이다. 등비급수는 $|r| < 1$일 때 수렴하며 합은 $\\frac{a}{1-r}$이다. 수렴의 필요조건: $\\lim a_n = 0$.\n\n**Step 1. **\n급수 $\\sum a_n$이 수렴하면, 반드시 $\\lim_{n\\to\\infty} a_n = 0$이다.\n\n**증명:** $S_n = a_1+a_2+\\cdots+a_n$이라 하면\n$a_n = S_n - S_{n-1}$\n$\\lim_{n\\to\\infty} a_n = \\lim_{n\\to\\infty}(S_n-S_{n-1}) = S-S = 0$\n\n단, 역은 성립하지 않는다. 예를 들어 조화급수 $\\sum\\frac{1}{n}$은 $a_n\\to 0$이지만 발산한다.\n\n**∴ 답: ① 0**\n\n**💡 포인트:** '수렴하면 일반항→0'은 필요조건이지 충분조건이이다. 수능에서 자주 출제되는 핵심 개념이다.\n\n**∴ 답: ① 0**\n\n② 1: 주어진 조건을 만족하지 않으므로 오답이다.\n③ ∞: 주어진 조건을 만족하지 않으므로 오답이다.\n④ 알 수 없다: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ -1: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 부분합의 극한을 구하거나, 등비급수의 수렴 조건을 활용한다.",
