    "explanation": "**[풀이]**\n\n**기본 개념:** 무한급수 $\\sum_{n=1}^{\\infty} a_n$의 합은 부분합의 극한 $\\lim_{n \\\\to \\infty} S_n$이다. 등비급수는 $|r| < 1$일 때 수렴하며 합은 $\\frac{a}{1-r}$이다. 수렴의 필요조건: $\\lim a_n = 0$.\n\n**Step 1. **\n귀류법\n$\\sum(a_n+b_n)$이 수렴한다고 가정하면,\n$\\sum b_n = \\sum(a_n+b_n) - \\sum a_n$\n수렴 - 수렴 = 수렴이 되어 $\\sum b_n$이 수렴해야 한다.\n\n그런데 $\\sum b_n$은 발산한다고 했으므로 **모순**이다.\n\n**Step 2. 검산**\n위 계산 과정을 대입하여 조건이 만족되는지 확인한다.\n\n**∴ 답: ② 항상 발산**\n\n① 항상 수렴: 주어진 조건을 만족하지 않으므로 오답이다.\n③ 수렴 또는 발산: 주어진 조건을 만족하지 않으므로 오답이다.\n④ 0으로 수렴: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 판정 불가: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**💡 포인트:** 부분합의 극한을 구하거나, 등비급수의 수렴 조건을 활용한다.",
