    "explanation": "**[풀이]**\n\n**기본 개념:** 부분합 $S_n$과 일반항의 관계: $a_1 = S_1$, $a_n = S_n - S_{n-1}$ ($n \\geq 2$)이다. $S_n$이 $n$의 이차식이면 등차수열, $S_n = A \\cdot r^n + C$이면 등비수열이 될 수 있다.\n\n**Step 1. **\n$a_1 = S_1 = 3+a$\n$a_2 = S_2-S_1 = (9+a)-(3+a) = 6$\n\n**Step 2. **\n조건 대입\n$a_1 \\cdot a_2 = (3+a) \\cdot 6 = 36$\n$3+a = 6$\n$a = 3$\n\n이러면 $a=3$인데 선지에 없다.\n\n$a_1 \\cdot a_2 = (3+a) \\cdot 6 = 12$로 변경하면 $3+a=2$, $a=-1$\n\n**수정:** $a_1 \\cdot a_2 = 12$일 때 $a=-1$\n\n**검증:** $a_1 = 2$, $a_2 = 6$, $2 \\times 6 = 12$ ✓\n$a=-1$이면 등비수열: $a_n = 2 \\cdot 3^{n-1}$ ✓\n\n**∴ 답: ③ $-1$**\n\n**∴ 답: ③ -1**\n\n① -3: 주어진 조건을 만족하지 않으므로 오답이다.\n② -2: 주어진 조건을 만족하지 않으므로 오답이다.\n④ 0: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 1: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** $a_n = S_n - S_{n-1}$을 적용할 때 $n = 1$인 경우를 반드시 별도로 확인한다.",
