    "explanation": "**[풀이]**\n\n**기본 개념:** 수열의 응용에서는 등차·등비수열의 일반항과 합 공식, 점화식의 풀이, 부분합과 일반항의 관계 등 여러 개념을 종합적으로 활용한다.\n\n**Step 1. **\n구간합\n$S_{10} = 100$\n$S_{20}-S_{10} = 400-100 = 300$\n\n**Step 2. **\n등차수열 확인: $100, 300, ?$의 공차는 200\n$S_{30}-S_{20} = 300+200 = 500$\n\n**Step 3. **\n$S_{30} = S_{20}+500 = 400+500 = 900$\n\n**검증:** $S_n = \\frac{d}{2}n^2+(a_1-\\frac{d}{2})n$에서\n$S_{10} = 50d+10a_1-5d = 45d+10a_1 = 100$\n$S_{20} = 200d+20a_1-10d = 190d+20a_1 = 400$\n\n(ii)$-2\\times$(i): $190d+20a_1-90d-20a_1 = 400-200$, $100d=200$, $d=2$\n$a_1 = \\frac{100-90}{10} = 1$\n$S_{30} = 45 \\cdot 30 \\cdot 2/30 ... S_{30} = \\frac{30 \\cdot 31}{2} \\cdot 2 + 30 \\cdot 1 - ... $\n\n간단히: $S_n = n^2$이면 $S_{10}=100$, $S_{20}=400$, $S_{30}=900$ ✓\n\n**∴ 답: ③ 900**\n\n**∴ 답: ③ 900**\n\n① 700: 주어진 조건을 만족하지 않으므로 오답이다.\n② 800: 주어진 조건을 만족하지 않으므로 오답이다.\n④ 1000: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 1100: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**💡 포인트:** 문제 조건을 수식으로 정확히 변환하고 기본 공식을 단계적으로 적용한다.",
