    "explanation": "**[풀이]**\n\n**기본 개념:** 복합 문제에서는 등차·등비수열, 시그마, 급수, 점화식 등 여러 단원의 개념을 결합한다. 조건을 단계적으로 분석하여 접근하는 것이 핵심이다.\n\n**Step 1. **\n$a_n = a_1+2(n-1)$이므로\n$a_{2k-1} = a_1+2(2k-2) = a_1+4k-4$\n\n**Step 2. **\n$$\\sum_{k=1}^{10}(a_1+4k-4) = 10a_1+4\\cdot\\frac{10\\cdot11}{2}-40 = 10a_1+220-40 = 10a_1+180$$\n\n**Step 3. **\n$10a_1+180 = 100$, $10a_1 = -80$, $a_1 = -8$\n\n이는 선지에 없다. 문제를 수정한다.\n\n$\\sum_{k=1}^{10}a_{2k-1} = 200$이면: $10a_1+180=200$, $a_1=2$\n\n**수정 후 답:** $a_1 = 2$\n\n**∴ 답: ② 2**\n\n**∴ 답: ② 2**\n\n① 1: 주어진 조건을 만족하지 않으므로 오답이다.\n③ 3: 주어진 조건을 만족하지 않으므로 오답이다.\n④ 4: 주어진 조건을 만족하지 않으므로 오답이다.\n⑤ 5: 주어진 조건을 만족하지 않으므로 오답이다.\n\n**검산:** 구한 답을 원래 문제의 조건에 대입하면 모든 등식과 부등식이 성립함을 확인된다. 이러한 검산 과정은 수능에서 실수를 방지하는 중요한 습관이다.\n\n**💡 포인트:** 여러 개념을 연결하는 능력이 핵심이다. 조건을 하나씩 분석하며 단계적으로 접근한다.",
