    "problem": "수열 $\\{a_n\\}$에서 $a_n = \\displaystyle\\sum_{k=1}^{n}\\frac{1}{k(k+1)}$일 때, $\\displaystyle\\sum_{n=1}^{\\infty}\\frac{1}{(n+1)a_n a_{n+1}}$의 값을 구하시오.",
    "answerType": "short",
