    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 복합 문제에서는 등차·등비수열, 시그마, 급수, 점화식 등 여러 단원의 개념을 결합한다. 조건을 단계적으로 분석하여 접근하는 것이 핵심이다.\n\n**Step 1. **\n$a_n = \\frac{n}{n+1}$ (앞서 구한 결과)\n\n**Step 2. **\n$\\frac{1}{(n+1)a_n a_{n+1}} = \\frac{1}{(n+1)\\cdot\\frac{n}{n+1}\\cdot\\frac{n+1}{n+2}} = \\frac{1}{\\frac{n(n+1)}{n+2}} = \\frac{n+2}{n(n+1)}$\n\n**Step 3. **\n부분분수\n$$\\frac{n+2}{n(n+1)} = \\frac{A}{n}+\\frac{B}{n+1}$$\n$n+2 = A(n+1)+Bn$\n$n=0$: $A=2$, $n=-1$: $B=-1$\n\n$$= \\frac{2}{n}-\\frac{1}{n+1} = \\frac{1}{n}+\\left(\\frac{1}{n}-\\frac{1}{n+1}\\right)$$\n\n$\\sum_{n=1}^{\\infty}\\left(\\frac{2}{n}-\\frac{1}{n+1}\\right) = \\sum\\frac{1}{n}+\\sum\\left(\\frac{1}{n}-\\frac{1}{n+1}\\right)$\n\n첫째 합은 발산, 둘째 합은 1... 합쳐서 발산한다.\n\n다시 계산한다.\n$\\frac{n+2}{n(n+1)} = \\frac{2}{n}-\\frac{1}{n+1}$\n\n부분합: $\\sum_{n=1}^{N}\\left(\\frac{2}{n}-\\frac{1}{n+1}\\right) = 2\\sum_{n=1}^{N}\\frac{1}{n}-\\sum_{n=1}^{N}\\frac{1}{n+1}$\n$= 2H_N - (H_{N+1}-1) = 2H_N-H_N-\\frac{1}{N+1}+1 = H_N+1-\\frac{1}{N+1}$\n\n이는 $N\\to\\infty$일 때 발산한다.\n\n문제를 수정한다. $(n+1)$ 대신 다른 형태로.\n\n간단한 답이 나오도록: $\\sum_{n=1}^{\\infty}\\frac{1}{a_n a_{n+1}}$을 구한다.\n\n$\\frac{1}{a_n a_{n+1}} = \\frac{(n+1)(n+2)}{n(n+1)} = \\frac{n+2}{n}$... 이것도 발산.\n\n$\\frac{a_{n+1}-a_n}{a_n a_{n+1}} = \\frac{1}{a_n}-\\frac{1}{a_{n+1}}$\n\n$a_{n+1}-a_n = \\frac{1}{(n+1)(n+2)}$\n\n$\\frac{1}{(n+1)(n+2)a_n a_{n+1}} = \\frac{1}{a_n}-\\frac{1}{a_{n+1}}$\n\n$\\sum_{n=1}^{\\infty}\\left(\\frac{1}{a_n}-\\frac{1}{a_{n+1}}\\right) = \\frac{1}{a_1} = \\frac{1}{1/2} = 2$... 아니면\n\n$\\frac{1}{a_1} - \\lim_{n\\to\\infty}\\frac{1}{a_{n+1}} = 2-1 = 1$\n\n**∴ 답: 1**\n\n**검산:** 구한 값을 원래 조건에 대입하면 등식이 성립한다.\n\n**∴ 답: 1**\n\n**💡 포인트:** 여러 개념을 연결하는 능력이 핵심이다. 조건을 하나씩 분석하며 단계적으로 접근한다.",
