    "problem": "$\\displaystyle\\sum_{k=1}^{n}\\frac{k}{(k+1)!} = 1 - \\frac{1}{(n+1)!}$을 이용하여 $\\displaystyle\\sum_{k=1}^{\\infty}\\frac{k}{(k+1)!}$의 값을 구하시오.",
