    "explanation": "**[풀이]**\n\n**기본 개념:** 무한급수 $\\sum_{k=1}^{\\infty} a_k$의 값은 부분합 $S_n = \\sum_{k=1}^{n} a_k$의 극한 $\\lim_{n \\to \\infty} S_n$으로 구한다. 유한합의 닫힌 형태가 주어지면 $n \\to \\infty$의 극한을 취하면 된다.\n\n**Step 1. 부분합 공식 확인**\n문제에서 $\\sum_{k=1}^{n} \\frac{k}{(k+1)!} = 1 - \\frac{1}{(n+1)!}$이 주어져 있다. 이것이 $S_n$의 닫힌 형태이다.\n\n**Step 2. 무한급수의 합 계산**\n$(n+1)!$은 $n \\to \\infty$일 때 발산하므로 $\\frac{1}{(n+1)!} \\to 0$이다.\n$$\\sum_{k=1}^{\\infty} \\frac{k}{(k+1)!} = \\lim_{n \\to \\infty}\\left(1 - \\frac{1}{(n+1)!}\\right) = 1 - 0 = 1$$\n\n**Step 3. 검산**\n$S_3 = \\frac{1}{2} + \\frac{1}{3} + \\frac{1}{8} = \\frac{12+8+3}{24} = \\frac{23}{24}$이고, $1 - \\frac{1}{4!} = \\frac{23}{24}$ ✓\n부분합이 1에 단조증가하며 접근하는 것을 확인된다.\n\n**∴ 답: 1**\n\n**💡 포인트:** $\\frac{k}{(k+1)!} = \\frac{(k+1)-1}{(k+1)!} = \\frac{1}{k!} - \\frac{1}{(k+1)!}$로 텔레스코핑 구조를 직접 유도할 수도 있다.",
