    "problem": "수열 $\\{a_n\\}$이 $a_1 = 1$, $S_n = n^2 a_n$ ($n \\geq 1$)을 만족할 때, $a_n$을 구하면?\n\n① $\\dfrac{2}{n(n+1)}$\n② $\\dfrac{1}{n(n+1)}$\n③ $\\dfrac{2}{n^2}$\n④ $\\dfrac{1}{n}$\n⑤ $\\dfrac{n+1}{n}$",
