    "answer": 0,
    "explanation": "**[풀이]**\n\n**기본 개념:** 부분합 $S_n$과 일반항의 관계 $a_n = S_n - S_{n-1}$ ($n \\geq 2$)을 이용한다. $S_n$이 $a_n$을 포함한 식이면 대입하여 점화식을 유도하고, 비의 곱(텔레스코핑 곱)으로 일반항을 구한다.\n\n**Step 1. 점화식 유도**\n$S_n = n^2 a_n$, $S_{n-1} = (n-1)^2 a_{n-1}$이므로 ($n \\geq 2$):\n$$a_n = n^2 a_n - (n-1)^2 a_{n-1}$$\n$$(1 - n^2)a_n = -(n-1)^2 a_{n-1}$$\n$$-(n-1)(n+1)a_n = -(n-1)^2 a_{n-1}$$\n양변을 $-(n-1)$로 나누면: $(n+1)a_n = (n-1)a_{n-1}$\n\n**Step 2. 텔레스코핑 곱**\n$$\\frac{a_n}{a_{n-1}} = \\frac{n-1}{n+1}$$\n$$a_n = a_1 \\prod_{k=2}^{n} \\frac{k-1}{k+1} = \\frac{1 \\cdot 2}{n(n+1)} = \\frac{2}{n(n+1)}$$\n\n**Step 3. 검증**\n$a_1 = \\frac{2}{2} = 1$ ✓, $a_2 = \\frac{2}{6} = \\frac{1}{3}$, $S_2 = \\frac{4}{3} = 4 \\cdot \\frac{1}{3}$ ✓\n\n**∴ 답: ① $\\dfrac{2}{n(n+1)}$**\n\n② $\\frac{1}{n(n+1)}$: $a_1 = \\frac{1}{2} \neq 1$이므로 오답이다.\n③ $\\frac{2}{n^2}$: $a_2 = \\frac{1}{2}$이지만 $S_2 \neq 4a_2$이므로 오답이다.\n④ $\\frac{1}{n}$: $S_2 = \\frac{3}{2} \neq 4 \\cdot \\frac{1}{2}$이므로 오답이다.\n⑤ $\\frac{n+1}{n}$: $a_1 = 2 \neq 1$이므로 오답이다.\n\n**💡 포인트:** $S_n = f(n) \\cdot a_n$ 꼴에서는 $a_n = S_n - S_{n-1}$을 대입하여 인접항 비의 점화식을 만들고, 텔레스코핑 곱을 활용한다.",
