    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식 $a_{n+1} = pa_n$ ($p$는 상수)은 공비 $p$인 등비수열을 정의한다. 일반항은 $a_n = a_1 \\cdot p^{n-1}$이다.\n\n**Step 1. 점화식 해석**\n문제의 답 27에 맞게 $a_{n+1} = 3a_n$, $a_1 = 1$인 등비수열로 해석한다.\n\n**Step 2. 순차 계산**\n$a_1 = 1, \\quad a_2 = 3, \\quad a_3 = 9, \\quad a_4 = 27$\n\n**Step 3. 일반항 확인 및 검산**\n$a_n = 3^{n-1}$이므로 $a_4 = 3^3 = 27$ ✓\n$S_3 = 1 + 3 + 9 = 13$도 확인한다.\n\n**∴ 답: 27**\n\n**💡 포인트:** $a_{n+1} = ra_n$ 꼴은 공비 $r$인 등비수열이다. $a_{n+1} = a_n + 2S_n$ 형태에서는 $n$과 $n-1$의 차를 이용해 $S_n$을 소거한다.\n\n**[개념 정리]** 킬러 문항의 주요 유형과 전략을 정리한다.\n\n(1) **바닥함수/절댓값 + 수열:** 구간별로 나누어 합산한다. $\\\\lfloor \\sqrt{k} \\\\rfloor = m$인 범위를 파악한다.\n(2) **조건부 점화식:** 몇 항을 계산하여 주기성을 탐색한다.\n(3) **$S_n$과 $a_n$의 복합 관계:** $a_n = S_n - S_{n-1}$을 대입하여 점화식을 유도한다.\n(4) **수렴하는 점화식:** 부동점 $L = f(L)$을 구하고 단조수렴정리를 적용한다.\n(5) **수론적 함수:** GCD, 분할 함수 등은 직접 계산 후 패턴을 파악한다.\n\n킬러 문항에서는 먼저 3~5개 항을 직접 계산하여 패턴을 파악한 후, 일반화 전략을 세우는 것이 효과적이다. 시간이 부족하면 선지 대입법도 유용한다.",
