    "explanation": "**[풀이]**\n\n**기본 개념:** 3항 선형 점화식 $a_{n+2} = pa_{n+1} + qa_n$의 일반항은 특성방정식 $x^2 = px + q$의 근을 이용한다. 두 근이 $\\alpha, \\beta$이면 $a_n = A\\alpha^n + B\\beta^n$이고, 초기조건으로 $A, B$를 결정한다.\n\n**Step 1. 특성방정식**\n$x^2 - 3x + 2 = 0$, $(x-1)(x-2) = 0$이므로 $x = 1, 2$\n\n**Step 2. 일반해와 계수 결정**\n$a_n = A + B \\cdot 2^n$\n$a_1 = A + 2B = 1$, $a_2 = A + 4B = 3$\n$(\\text{ii}) - (\\text{i})$: $2B = 2$, $B = 1$, $A = -1$\n\n**Step 3. 일반항 및 검증**\n$a_n = 2^n - 1$\n$a_3 = 7 = 3 \\times 3 - 2 \\times 1$ ✓\n\n**∴ 답: ① $2^n - 1$**\n\n② $2^n+1$: $a_1 = 3 \neq 1$. ③ $2^{n-1}+1$: $a_1 = 2 \neq 1$. ④ $2^n - n$: $a_3 = 5 \neq 7$. ⑤ $3 \\cdot 2^{n-1}-1$: $a_1 = 2 \neq 1$.\n\n**💡 포인트:** 3항 점화식은 특성방정식으로 풉니다. 초기값 2개로 미지수 2개를 결정한다.\n\n**[개념 정리]** 킬러 문항의 주요 유형과 전략을 정리한다.\n\n(1) **바닥함수/절댓값 + 수열:** 구간별로 나누어 합산한다. $\\\\lfloor \\sqrt{k} \\\\rfloor = m$인 범위를 파악한다.\n(2) **조건부 점화식:** 몇 항을 계산하여 주기성을 탐색한다.\n(3) **$S_n$과 $a_n$의 복합 관계:** $a_n = S_n - S_{n-1}$을 대입하여 점화식을 유도한다.\n(4) **수렴하는 점화식:** 부동점 $L = f(L)$을 구하고 단조수렴정리를 적용한다.\n(5) **수론적 함수:** GCD, 분할 함수 등은 직접 계산 후 패턴을 파악한다.\n\n킬러 문항에서는 먼저 3~5개 항을 직접 계산하여 패턴을 파악한 후, 일반화 전략을 세우는 것이 효과적이다. 시간이 부족하면 선지 대입법도 유용한다.",
