    "explanation": "**[풀이]**\n\n**기본 개념:** 이중 시그마에서 안쪽 합 $\\sum_{j=1}^{k} j = \\frac{k(k+1)}{2}$를 먼저 구한다. $\\sum_{k=1}^{n} \\frac{k(k+1)}{2} = \\frac{n(n+1)(n+2)}{6}$은 삼각수의 누적합 공식이다.\n\n**Step 1. 공식에 대입**\n$$\\sum_{k=1}^{10}\\left(\\sum_{j=1}^{k} j\\right) = \\frac{10 \\times 11 \\times 12}{6}$$\n\n**Step 2. 계산**\n$$= \\frac{1320}{6} = 220$$\n\n**Step 3. 검산**\n$\\frac{1}{2}(\\sum k^2 + \\sum k) = \\frac{1}{2}(385 + 55) = 220$ ✓\n\n**∴ 답: 220**\n\n**💡 포인트:** $\\sum_{k=1}^{n} T_k = \\frac{n(n+1)(n+2)}{6}$에서 $T_k = \\frac{k(k+1)}{2}$는 $k$번째 삼각수이다. 이 공식은 조합 $\\binom{n+2}{3}$과도 같다.\n\n**[개념 정리]** 킬러 문항의 주요 유형과 전략을 정리한다.\n\n(1) **바닥함수/절댓값 + 수열:** 구간별로 나누어 합산한다. $\\\\lfloor \\sqrt{k} \\\\rfloor = m$인 범위를 파악한다.\n(2) **조건부 점화식:** 몇 항을 계산하여 주기성을 탐색한다.\n(3) **$S_n$과 $a_n$의 복합 관계:** $a_n = S_n - S_{n-1}$을 대입하여 점화식을 유도한다.\n(4) **수렴하는 점화식:** 부동점 $L = f(L)$을 구하고 단조수렴정리를 적용한다.\n(5) **수론적 함수:** GCD, 분할 함수 등은 직접 계산 후 패턴을 파악한다.\n\n킬러 문항에서는 먼저 3~5개 항을 직접 계산하여 패턴을 파악한 후, 일반화 전략을 세우는 것이 효과적이다. 시간이 부족하면 선지 대입법도 유용한다.",
