    "explanation": "**[풀이]**\n\n**기본 개념:** $\\sum_{k=1}^{n} k \\cdot r^k$ 형태(등차×등비 급수)는 $S$에 공비 $r$을 곱한 뒤 빼는 **차분법**으로 구한다. $S - rS$를 계산하면 등비급수가 된다.\n\n**Step 1. 차분법**\n$S_n = \\sum_{k=1}^{n} k \\cdot 3^k$, $3S_n = \\sum_{k=1}^{n} k \\cdot 3^{k+1}$\n$S_n - 3S_n = -2S_n = \\sum_{k=1}^{n} 3^k - n \\cdot 3^{n+1}$\n\n**Step 2. 등비급수 계산**\n$-2S_n = \\frac{3(3^n-1)}{2} - n \\cdot 3^{n+1} = \\frac{(1-2n) \\cdot 3^{n+1} - 3}{2}$\n$S_n = \\frac{(2n-1) \\cdot 3^{n+1} + 3}{4}$\n\n**Step 3. 검증**\n$n=1$: $\\frac{1 \\cdot 9 + 3}{4} = 3$ ✓, $n=2$: $\\frac{3 \\cdot 27 + 3}{4} = 21 = 3+18$ ✓\n\n**∴ 답: ① $\\dfrac{(2n-1) \\cdot 3^{n+1}+3}{4}$**\n\n② 분자가 $-3$이면 $n=1$에서 $\\frac{3}{2} \neq 3$. ③~⑤도 $n=1$ 대입 시 3이 아닙니다.\n\n**💡 포인트:** 등차×등비 급수의 공식 유도법(차분법)을 숙지하면 여러 변형에 대응할 수 있다.",
