    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열에서 두 항 $a_m$, $a_n$이 주어지면 공차 $d = \\frac{a_n - a_m}{n - m}$으로 구한다. 이는 등차수열의 일반항 $a_n = a_1 + (n-1)d$에서 유도된다.\n\n**Step 1. 공차 공식 적용**\n$$d = \\frac{a_9 - a_4}{9 - 4} = \\frac{26 - 11}{5} = \\frac{15}{5} = 3$$\n\n**Step 2. 검증**\n$a_4 = a_1 + 3d = 11$에서 $a_1 = 11 - 9 = 2$\n$a_9 = 2 + 8 \\times 3 = 26$ ✓\n\n**∴ 답: ② $3$**\n\n① $d=2$: $a_9 - a_4 = 10 \neq 15$. ③ $d=4$: $a_9 - a_4 = 20 \neq 15$. ④ $d=5$: $a_9 - a_4 = 25 \neq 15$. ⑤ $d=6$: $a_9 - a_4 = 30 \neq 15$.\n\n**💡 포인트:** $a_m - a_n = (m-n)d$를 이용하면 공차를 빠르게 구한다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
