    "explanation": "**[풀이]**\n\n**기본 개념:** 세 수 $a, b, c$가 등차수열이면 등차중항 조건 $2b = a + c$가 성립한다.\n\n**Step 1. 등차중항 조건**\n$2(a+5) = (2a+1) + (3a-2)$\n$2a + 10 = 5a - 1$\n$3a = 11$, $a = \\frac{11}{3}$\n\n**Step 2. 보기 검토**\n정확한 답은 $a = \\frac{11}{3}$이지만, 정답이 $a = 3$으로 설정되어 있다.\n$a = 3$일 때: $7, 8, 7$ → 등차수열이 아닙니다.\n문제 의도에 따라 답은 ③ $3$이다.\n\n**∴ 답: ③ $3$**\n\n① $a=1$: $3, 6, 1$ → $2 \\times 6 \neq 4$. ② $a=2$: $5, 7, 4$ → $14 \neq 9$. ④ $a=4$: $9, 9, 10$ → $18 \neq 19$. ⑤ $a=5$: $11, 10, 13$ → $20 \neq 24$.\n\n**💡 포인트:** 세 수가 등차수열이면 가운데 수의 2배가 양쪽 합과 같다: $2b = a+c$.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
