    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열에서 연속 등간격 부분합 $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 공차가 $n^2 d$인 등차수열을 이룹니다.\n\n**Step 1. 등간격 부분합의 등차성**\n$S_{10} = 100$, $S_{20} - S_{10} = 400 - 100 = 300$\n이 세 수 $100, 300, S_{30}-S_{20}$은 등차수열이다.\n\n**Step 2. 공차 계산**\n공차 $= 300 - 100 = 200$\n\n**Step 3. $S_{30}$ 계산**\n$S_{30} - S_{20} = 300 + 200 = 500$\n$S_{30} = 400 + 500 = 900$\n\n**Step 4. 검산**\n$S_n = \\frac{n}{2}(2a_1 + (n-1)d)$에서 $S_{10} = 5(2a_1+9d) = 100$, $S_{20} = 10(2a_1+19d) = 400$\n두 식에서 $a_1 = 1, d = 2$이면 $S_{30} = 15(2+58) = 900$ ✓\n\n**∴ 답: 900**\n\n**💡 포인트:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$이 등차수열임을 이용하면 연립방정식 없이 빠르게 풀 수 있다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
