    "explanation": "**[풀이]**\n\n**기본 개념:** 공차가 음수인 등차수열에서 $S_n$의 최댓값은 마지막 양수 항까지의 합이다. 즉, $a_n \\geq 0$이고 $a_{n+1} < 0$인 $n$을 찾으면 된다.\n\n**Step 1. 일반항 구하기**\n$a_n = 50 + (n-1)(-4) = 54 - 4n$\n\n**Step 2. $a_n \\geq 0$인 최대 $n$**\n$54 - 4n \\geq 0$ → $n \\leq 13.5$\n따라서 $a_{13} = 54 - 52 = 2 > 0$, $a_{14} = 54 - 56 = -2 < 0$\n\n**Step 3. 검산**\n$S_{13} = \\frac{13(50+2)}{2} = \\frac{13 \\times 52}{2} = 338$\n$S_{14} = \\frac{14(50-2)}{2} = 336 < 338$ ✓\n\n**∴ 답: 13**\n\n**💡 포인트:** $d < 0$인 등차수열에서 $S_n$ 최대는 $a_n \\geq 0$인 최대 $n$에서 달성된다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
