    "explanation": "**[풀이]**\n\n**기본 개념:** $S_n$이 $n$에 대한 이차식이면 수열 $\\{a_n\\}$은 등차수열이다. $a_n = S_n - S_{n-1}$ ($n \\geq 2$)로 일반항을 구한다.\n\n**Step 1. $a_1$ 계산**\n$a_1 = S_1 = 2 - 3 = -1$\n\n**Step 2. 일반항 ($n \\geq 2$)**\n$a_n = (2n^2 - 3n) - (2(n-1)^2 - 3(n-1))$\n$= 2n^2 - 3n - 2n^2 + 4n - 2 + 3n - 3 = 4n - 5$\n\n**Step 3. $n=1$ 확인 및 공차**\n$a_1 = 4(1) - 5 = -1$ ✓, $d = a_2 - a_1 = 3 - (-1) = 4$\n\n**∴ 답: ① $a_1 = -1, d = 4$**\n\n② $a_1=1$: $S_1 = -1 \neq 1$. ③ $d=2$이면 $a_2=1$이지만 $S_2 = 2 \n\n**💡 포인트:** $S_n$이 이차식이면 등차수열이고, $a_n = S_n - S_{n-1}$는 일차식이 된다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
