    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열에서 문자로 주어진 두 조건의 차를 이용하면 공차를 결정할 수 있다. $a_p = q, a_q = p$이면 $(p-q)d = q-p$에서 $d = -1$이다.\n\n**Step 1. 공차 결정**\n$a_p - a_q = (p-q)d = q - p = -(p-q)$\n$p \neq q$이므로 $d = -1$\n\n**Step 2. 첫째항 계산**\n$a_p = a_1 + (p-1)(-1) = q$에서 $a_1 = q + p - 1$\n\n**Step 3. $a_{p+q}$ 계산**\n$a_{p+q} = a_1 + (p+q-1)d = (p+q-1) + (p+q-1)(-1) = 0$\n\n**∴ 답: ① $0$**\n\n② $1$: 검산에서 $0$이 맞다. ③ $-1$, ④ $p+q$, ⑤ $p-q$ 모두 일반적으로 $0$이 아니므로 오답이다.\n\n**💡 포인트:** $a_p = q, a_q = p$인 등차수열에서 $a_{p+q} = 0$은 아름다운 결과이다. 공차 $d = -1$이 핵심이다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
