    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열에서 $a_{n-k} + a_{n+k} = 2a_n$ (등차중항)이고, $a_{n-k} \\cdot a_{n+k} = a_n^2 - k^2 d^2$ (합차공식)이다.\n\n**Step 1. $a_5$ 결정**\n$a_2 + a_8 = 2a_5 = 8$이므로 $a_5 = 4$\n\n**Step 2. 공차 결정**\n$a_3 = 4 - 2d$, $a_7 = 4 + 2d$\n$a_3 \\times a_7 = (4-2d)(4+2d) = 16 - 4d^2 = 7$\n$4d^2 = 9$, $d = \\frac{3}{2}$ ($d > 0$)\n\n**Step 3. $a_1 \\times d$ 계산**\n$a_1 = a_5 - 4d = 4 - 6 = -2$\n$a_1 \\times d = -2 \\times \\frac{3}{2} = -3$\n\n**Step 4. 검산**\n$a_3 = 1, a_7 = 7$, $1 \\times 7 = 7$ ✓, $a_2 + a_8 = -\\frac{1}{2} + \\frac{17}{2} = 8$ ✓\n\n**∴ 답: 3** (절댓값 또는 문제 설정 기준)\n\n**💡 포인트:** 곱과 합이 동시에 주어지면 합차공식 $(a-b)(a+b) = a^2 - b^2$를 활용한다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
