    "problem": "양의 정수로 이루어진 등차수열 $\\\\{a_n\\\\}$에서 $a_1 = 2$이고 $\\frac{1}{a_1 a_2} + \\frac{1}{a_2 a_3} + \\cdots + \\frac{1}{a_9 a_{10}} = \\frac{9}{20}$일 때, 공차 $d$의 값을 구하시오.",
    "answerType": "short",
