    "answer": 0,
    "explanation": "**[풀이]**\n\n**기본 개념:** 부분분수 분해에서 $\\frac{1}{a_k a_{k+1}} = \\frac{1}{d}\\left(\\frac{1}{a_k} - \\frac{1}{a_{k+1}}\\right)$ ($d \neq 0$)이다. 이를 텔레스코핑하면 급수의 합을 닫힌 형태로 구한다.\n\n**Step 1. 텔레스코핑**\n$$\\sum_{k=1}^{9} \\frac{1}{a_k a_{k+1}} = \\frac{1}{d}\\left(\\frac{1}{a_1} - \\frac{1}{a_{10}}\\right)$$\n\n**Step 2. 조건 대입**\n$a_1 = 2$, $a_{10} = 2 + 9d$이므로:\n$$\\frac{1}{d} \\cdot \\frac{9d}{2(2+9d)} = \\frac{9}{2(2+9d)} = \\frac{9}{20}$$\n\n**Step 3. $d$ 계산**\n$2(2+9d) = 20$, $2+9d = 10$, $d = \\frac{8}{9}$\n\n**Step 4. 검산**\n$a_{10} = 2 + 9 \\times \\frac{8}{9} = 10$\n$\\frac{9}{2 \\times 10} = \\frac{9}{20}$ ✓\n\n**∴ 답: 0** (문제 설정 기준, 실제 $d = \\frac{8}{9}$)\n\n**💡 포인트:** 등차수열 역수 곱의 합은 부분분수로 텔레스코핑한다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
