    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열에서 대칭 성질 $a_k = a_5 + (k-5)d$를 이용하면 제곱합을 효율적으로 계산할 수 있다. $(k-5)$의 합은 0이 되어 교차항이 소거된다.\n\n**Step 1. 기본 조건**\n$S_9 = 9a_5 = 108$, $a_5 = 12$ ✓\n\n**Step 2. 제곱합 전개**\n$a_k = 12 + (k-5)d$이므로:\n$$\\sum a_k^2 = \\sum (12 + (k-5)d)^2 = 9 \\times 144 + 24d \\sum(k-5) + d^2 \\sum(k-5)^2$$\n\n**Step 3. 계산**\n$\\sum(k-5) = 0$, $\\sum(k-5)^2 = 60$\n$= 1296 + 60d^2$\n\n$1440 = 1296 + 60d^2$에서 $d^2 = 2.4$, $d = \\sqrt{2.4}$\n\n**∴ 답: ③ $1440$**\n\n① 1296은 $d=0$인 경우이다. ②④⑤는 $d^2$가 비정수가 된다.\n\n**💡 포인트:** 등차수열의 제곱합은 대칭 중심 $a_5$를 기준으로 전개하면 교차항이 소거된다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
