    "explanation": "**[풀이]**\n\n**기본 개념:** 등차수열의 항들의 곱의 최댓값을 구할 때, AM-GM 부등식을 활용한다. 곱이 최대가 되려면 모든 항이 같아야 한다.\n\n**Step 1. $a_5$ 결정**\n$a_3 + a_5 + a_7 = 3a_5 = 45$, $a_5 = 15$\n\n**Step 2. 곱 표현**\n$a_2 = 15 - 3d$, $a_5 = 15$, $a_8 = 15 + 3d$\n$a_2 \\cdot a_5 \\cdot a_8 = 15(15-3d)(15+3d) = 15(225 - 9d^2)$\n\n**Step 3. 최댓값**\n$225 - 9d^2$는 $d = 0$일 때 최대이므로:\n최댓값 $= 15 \\times 225 = 3375$\n\n**∴ 답: ② $3375$**\n\n① 2025: $15 \\times 135$이 필요하지만 $225-9d^2=135$에서 $d^2=10$. ③④⑤도 $d \neq 0$이므로 최댓값이 아닙니다.\n\n**💡 포인트:** AM-GM에 의해 곱의 최대는 합이 일정할 때 모든 값이 같을 때 달성된다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
