    "problem": "공차가 자연수인 등차수열 $\\\\{a_n\\\\}$이 $a_1 = 1$이고 $a_p = p^2$을 만족하는 자연수 $p$가 존재할 때, 가능한 모든 $d$의 합을 구하시오.",
