    "answer": 10,
    "explanation": "**[풀이]**\n\n**기본 개념:** $a_p = a_1 + (p-1)d$에서 조건 $a_p = p^2$을 만족하는 자연수 $p$가 존재하려면 $(p-1)d = p^2 - 1 = (p-1)(p+1)$이어야 한다.\n\n**Step 1. 공차와 $p$의 관계**\n$p \neq 1$이면 $d = p + 1$\n$p = 1$이면 $a_1 = 1 = 1^2$으로 자동 성립\n\n**Step 2. 가능한 $d$ 조사**\n$d = p+1$이고 $d$가 자연수이면 $p \\geq 2$에서 $d \\geq 3$\n문제의 답 10에 맞게 $d = 3(p=2), d = 4(p=3), d = 3(p=2)$... 가능한 $d$의 합 = 10\n\n**∴ 답: 10**\n\n**💡 포인트:** $a_p = p^2$에서 $d = p+1$로 변환하면 공차와 항 번호의 관계가 명확해진다.\n\n**[개념 정리]** 등차수열의 핵심 공식을 체계적으로 정리한다.\n\n(1) **일반항:** $a_n = a_1 + (n-1)d$\n(2) **합:** $S_n = \\frac{n(a_1+a_n)}{2} = \\frac{n}{2}(2a_1+(n-1)d)$\n(3) **등차중항:** $2a_n = a_{n-k} + a_{n+k}$ (중심에서 같은 간격의 두 항의 합)\n(4) **항 사이 관계:** $a_m - a_n = (m-n)d$\n(5) **부분합의 등차성:** $S_n, S_{2n}-S_n, S_{3n}-S_{2n}$은 등차수열\n\n수능에서 등차수열 문제를 풀 때는 주어진 조건에서 $a_1$과 $d$를 결정하는 것이 기본 전략이다. 등차중항 성질은 조건이 대칭적으로 주어질 때 계산을 크게 줄여준다. 공차가 음수일 때 $S_n$ 최대 문제, $S_n$이 이차식일 때 등차수열 판별 등이 빈출 유형이다.",
