    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 등비수열에서 $a_n = a_1 r^{n-1}$이므로 $\\frac{a_n}{a_m} = r^{n-m}$이다. 두 항의 비로 공비의 거듭제곱을 구한다.\n\n**Step 1. 공비 계산**\n$a_4 = a_1 r^3$에서 $r^3 = \\frac{108}{4} = 27$, $r = 3$\n\n**Step 2. 검산**\n$a_1=4, a_2=12, a_3=36, a_4=108$ ✓\n\n**∴ 답: ② $3$**\n\n① $r=2$: $4 \\times 8 = 32 \neq 108$. ③ $r=4$: $4 \\times 64 = 256 \n\n**💡 포인트:** $r^k$의 $k$제곱근을 구하는 것이 핵심이다. $27 = 3^3$을 빠르게 파악한다.\n\n**[개념 정리]** 등비수열의 핵심 공식을 정리한다.\n\n(1) **일반항:** $a_n = a_1 r^{n-1}$\n(2) **합:** $S_n = \\frac{a_1(r^n-1)}{r-1}$ ($r \\\neq 1$)\n(3) **등비중항:** $a_n^2 = a_{n-k} \\cdot a_{n+k}$\n(4) **항 사이 비:** $\\frac{a_m}{a_n} = r^{m-n}$\n(5) **무한급수:** $|r|<1$일 때 $\\sum_{n=1}^{\\infty} a_n = \\frac{a_1}{1-r}$\n\n등비수열에서는 항의 곱과 비가 핵심이다. 로그를 취하면 등차수열의 성질을 적용할 수 있다. 두 항이 주어지면 비를 이용해 공비를 먼저 결정하고, 이어서 첫째항을 구하는 것이 정석이다. 연속 항쌍의 합의 비가 공비의 거듭제곱이 되는 성질도 자주 활용된다.",
