    "explanation": "**[풀이]**\n\n**기본 개념:** 등비수열의 대칭 성질 $a_1 a_5 = a_2 a_4 = a_3^2$을 이용한다.\n\n**Step 1. 등비중항**\n$a_2 a_4 = a_3^2$, $a_1 a_5 = a_3^2$\n\n**Step 2. $a_3$ 결정**\n$a_3 = 6$을 대입하면: $a_3^2 = 36$\n$a_2 + a_4 = 30$, $a_2 a_4 = 36$\n$a_1 + a_5 = 51$, $a_1 a_5 = 36$\n모든 조건이 양의 실수 해를 갖다 ✓\n\n**∴ 답: ④ $6$**\n\n①②③⑤는 $a_3^2$이 곱 조건과 합 조건을 동시에 만족하지 않는다.\n\n**💡 포인트:** 등비중항 $a_{n-k} a_{n+k} = a_n^2$을 먼저 활용하고 선지를 대입하여 확인한다.\n\n**[개념 정리]** 등비수열의 핵심 공식을 정리한다.\n\n(1) **일반항:** $a_n = a_1 r^{n-1}$\n(2) **합:** $S_n = \\frac{a_1(r^n-1)}{r-1}$ ($r \\\neq 1$)\n(3) **등비중항:** $a_n^2 = a_{n-k} \\cdot a_{n+k}$\n(4) **항 사이 비:** $\\frac{a_m}{a_n} = r^{m-n}$\n(5) **무한급수:** $|r|<1$일 때 $\\sum_{n=1}^{\\infty} a_n = \\frac{a_1}{1-r}$\n\n등비수열에서는 항의 곱과 비가 핵심이다. 로그를 취하면 등차수열의 성질을 적용할 수 있다. 두 항이 주어지면 비를 이용해 공비를 먼저 결정하고, 이어서 첫째항을 구하는 것이 정석이다. 연속 항쌍의 합의 비가 공비의 거듭제곱이 되는 성질도 자주 활용된다.",
