    "explanation": "**[풀이]**\n\n**기본 개념:** $\\frac{k}{(k+1)!} = \\frac{(k+1)-1}{(k+1)!} = \\frac{1}{k!} - \\frac{1}{(k+1)!}$로 텔레스코핑 구조를 유도한다.\n\n**Step 1. 변형**\n$\\frac{k}{(k+1)!} = \\frac{1}{k!} - \\frac{1}{(k+1)!}$\n\n**Step 2. 텔레스코핑**\n$\\sum_{k=1}^{n} = \\frac{1}{1!} - \\frac{1}{(n+1)!} = 1 - \\frac{1}{(n+1)!}$\n\n**∴ 답: ① $1 - \\frac{1}{(n+1)!}$**\n\n②~⑤는 $n=1$ 대입 시 $\\frac{1}{2}$가 되지 않는다.\n\n**💡 포인트:** 분자를 $(k+1)-1$로 분해하면 팩토리얼 텔레스코핑이 된다.\n\n**[개념 정리]** 수열의 합에서 반드시 알아야 할 공식과 기법이다.\n\n(1) $\\sum_{k=1}^{n} k = \\frac{n(n+1)}{2}$\n(2) $\\sum k^2 = \\frac{n(n+1)(2n+1)}{6}$\n(3) $\\sum k^3 = \\left(\\frac{n(n+1)}{2}\\right)^2$\n(4) **부분분수:** $\\frac{1}{k(k+d)} = \\frac{1}{d}\\left(\\frac{1}{k}-\\frac{1}{k+d}\\right)$ → 텔레스코핑\n(5) **등차×등비:** $\\sum kr^k$는 $S-rS$ 차분법\n(6) **유리화:** $\\frac{1}{\\sqrt{k+1}+\\sqrt{k}} = \\sqrt{k+1}-\\sqrt{k}$ → 텔레스코핑\n\n이 여섯 가지 도구를 마스터하면 수열의 합 문제 대부분을 해결할 수 있다. 시그마의 선형성을 이용하여 복잡한 식을 기본 형태로 분리하는 것이 첫 단계이다.",
