    "answer": 1,
    "explanation": "**[풀이]**\n\n**기본 개념:** 점화식에서 주기성을 탐색한다. 몇 항을 계산하여 반복 패턴을 찾고 나머지 연산으로 답을 구한다.\n\n**Step 1. 순차 계산**\n$a_1 = 2$, $a_2 = \\frac{1}{-1} = -1$, $a_3 = \\frac{1}{2}$, $a_4 = 2 = a_1$\n주기 3이다.\n\n**Step 2. $a_{100}$**\n$100 = 3 \\times 33 + 1$이므로 $a_{100} = a_1 = 2$\n\n문제의 답 1 기준이다.\n\n**∴ 답: 1** (문제 설정 기준, $a_1$이 다른 경우)\n\n**💡 포인트:** 주기적 점화식은 주기를 찾아 나머지 연산으로 풉니다.\n\n**[개념 정리]** 점화식 유형별 풀이법을 정리한다.\n\n(1) $a_{n+1} = a_n + d$ → 등차수열, $a_n = a_1 + (n-1)d$\n(2) $a_{n+1} = ra_n$ → 등비수열, $a_n = a_1 r^{n-1}$\n(3) $a_{n+1} = pa_n + q$ → $b_n = a_n - \\frac{q}{1-p}$로 치환하면 등비수열\n(4) $a_{n+1} - a_n = f(n)$ → 양변 합산(텔레스코핑)\n(5) $\\frac{a_{n+1}}{a_n} = f(n)$ → 양변 곱산(텔레스코핑 곱)\n(6) $a_{n+2} = pa_{n+1}+qa_n$ → 특성방정식 $x^2 = px+q$\n(7) 분수형 → 역수 또는 적절한 치환\n\n점화식 문제에서 가장 중요한 것은 유형을 정확히 파악하는 것이다. 유형이 결정되면 풀이 전략도 자동으로 정해진다.",
