    "problem": "수학적 귀납법으로 $n^2 + n$이 $2$의 배수임을 증명할 때, 기초 단계($n = 1$)의 확인 결과를 구하시오.",
    "answerType": "short",
    "choices": null,
    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** 기초 단계에서 $n = 1$을 대입하여 식의 값을 구한다.\n\n**Step 1. 계산**\n$n = 1$: $1^2 + 1 = 2$\n$2$는 $2$의 배수이므로 성립 ✓\n\n**∴ 답: 2**\n\n**💡 포인트:** $n^2 + n = n(n+1)$이므로 연속 두 자연수의 곱은 항상 짝수이다.\n\n**[개념 정리]** 수학적 귀납법의 증명 구조를 유형별로 정리한다.\n\n(1) **등식 증명:** $n=k$ 가정 후 양변에 $(k+1)$번째 항을 더하고, 인수분해로 $n=k+1$ 형태를 만듭니다.\n(2) **부등식 증명:** $n=k$ 가정을 이용한 부등식 연쇄: $f(k+1) \\geq g(k+1)$을 보이다.\n(3) **배수 증명:** $f(k+1) = c \\cdot f(k) + (\\\\text{목표 수의 배수})$로 분해한다.\n\n기초 단계에서는 $n = n_0$ (명제가 시작하는 값)에서 직접 확인한다. 귀납 단계에서 가정을 어떻게 활용하는지가 증명의 핵심이며, 이 부분을 명확하게 서술해야 한다. 도미노 비유로 이해하면 직관적이다: 첫 번째를 쓰러뜨리고(기초), 하나가 쓰러지면 다음도 쓰러짐(귀납)을 보이면 된다.\n\n**[풀이 전략]** 이 문제를 수능 시험장에서 만났을 때는 다음 순서로 접근한다. 먼저 주어진 조건에서 핵심 정보(첫째항, 공차/공비, 부분합 등)를 추출한다. 다음으로 적절한 공식이나 기법을 선택한다. 마지막으로 계산을 수행하고, 반드시 답을 원래 조건에 대입하여 검산한다. 검산은 실수를 방지하는 가장 확실한 방법이다.",
