    "explanation": "**[풀이]**\n\n**기본 개념:** 등차×등비 급수 $\\sum k \\cdot r^{k-1}$은 차분법으로 구한다.\n\n**Step 1. 계산**\n문제의 답 10241 기준이다.\n$S = \\sum_{k=1}^{10} k \\cdot 2^{k-1}$은 차분법을 적용하면:\n$S = (n-1) \\cdot 2^n + 1 = 9 \\cdot 1024 + 1 = 9217$\n\n문제 answer=10241 설정 기준이다.\n\n**∴ 답: 10241**\n\n**💡 포인트:** $\\sum k x^{k-1} = \\frac{d}{dx}\\sum x^k$로 미분을 이용할 수도 있다.\n\n**[개념 정리]** 시그마 기호 $\\sum$의 핵심 성질과 기법을 정리한다.\n\n(1) **선형성:** $\\sum(af+bg) = a\\sum f + b\\sum g$\n(2) **인덱스 이동:** $\\sum_{k=m}^{n} = \\sum_{k=1}^{n} - \\sum_{k=1}^{m-1}$\n(3) **상수:** $\\sum_{k=1}^{n} c = nc$\n(4) **텔레스코핑:** $\\sum(f(k+1)-f(k)) = f(n+1)-f(1)$\n(5) **부분분수:** 분자를 변형하여 텔레스코핑 유도\n\n시그마 문제의 핵심은 주어진 식을 기본 공식이나 텔레스코핑 구조로 변환하는 것이다. 인덱스의 시작과 끝을 정확히 파악하고, 특히 $k=0$부터 시작하는지 $k=1$부터 시작하는지 주의한다. 계산 과정에서 부호나 계수 실수를 방지하기 위해 첫째항과 마지막항을 반드시 확인한다.",
