    "explanation": "**[풀이]**\n\n**기본 개념:** 교대 조화급수 $\\sum \\frac{(-1)^{n+1}}{n}$은 라이프니츠 판정법에 의해 수렴하며, 합은 $\\ln 2$이다.\n\n**Step 1. 수렴 확인**\n$\\frac{1}{n}$은 단조감소하고 0에 수렴하므로 라이프니츠 판정법에 의해 수렴한다.\n\n**Step 2. 합**\n$\\ln(1+x) = x - \\frac{x^2}{2} + \\frac{x^3}{3} - \\cdots$에서 $x=1$: $\\ln 2$\n\n**∴ 답: ① $\\ln 2$**\n\n②~④는 다른 값. ⑤ 수렴하므로 발산이 아닙니다.\n\n**💡 포인트:** 교대 조화급수의 합은 $\\ln 2 \\approx 0.693$이다.\n\n**[개념 정리]** 무한급수의 수렴 판정법을 체계적으로 정리한다.\n\n(1) **등비급수:** $|r|<1$이면 $\\frac{a}{1-r}$로 수렴, $|r| \\geq 1$이면 발산\n(2) **$p$-급수:** $\\sum \\frac{1}{n^p}$는 $p>1$이면 수렴, $p \\leq 1$이면 발산\n(3) **텔레스코핑:** 부분합 $S_N$을 구한 후 $\\lim_{N \\\\to \\infty} S_N$\n(4) **비율판정법:** $\\lim \\frac{|a_{n+1}|}{|a_n|} < 1$이면 절대수렴\n(5) **교대급수(라이프니츠):** $|a_n|$이 단조감소하고 0에 수렴하면 수렴\n\n가장 중요한 것은 일반항의 극한이 0이 아니면 급수는 반드시 발산한다는 것이다(발산 판정법). 그러나 $\\lim a_n = 0$이 수렴의 충분조건은 아닙니다(조화급수가 대표적 반례이다).",
