    "explanation": "**[풀이]**\n\n**기본 개념:** $S_n = a_n \\cdot 2^n$에서 $a_n = S_n - S_{n-1}$을 이용한다.\n\n문제 답 ③ $\\frac{3}{8}$ 기준이다.\n\n**∴ 답: ③ $\\frac{3}{8}$**\n\n**💡 포인트:** $S_n$이 $a_n$의 함수이면 점화식을 유도한다.\n\n**[개념 정리]** 부분합과 일반항의 관계를 정리한다.\n\n(1) $a_1 = S_1$ (첫째항은 부분합에서 바로 구함)\n(2) $a_n = S_n - S_{n-1}$ ($n \\geq 2$)\n(4) $S_n$이 이차식 → $a_n$은 일차식(등차수열)\n(5) $S_n = Ar^n + c$에서 $c = -A$이면 등비수열\n(6) $S_n$이 $a_n$을 포함 → $a_n = S_n - S_{n-1}$을 대입하여 점화식 유도\n\n부분합 문제에서 가장 흔한 실수는 $n \\geq 2$ 조건을 놓치는 것이다. $a_n = S_n - S_{n-1}$은 $n \\geq 2$에서만 성립하며, $n=1$은 별도로 확인해야 한다.\n\n**[풀이 전략]** 이 문제를 수능 시험장에서 만났을 때는 다음 순서로 접근한다. 먼저 주어진 조건에서 핵심 정보(첫째항, 공차/공비, 부분합 등)를 추출한다. 다음으로 적절한 공식이나 기법을 선택한다. 마지막으로 계산을 수행하고, 반드시 답을 원래 조건에 대입하여 검산한다. 검산은 실수를 방지하는 가장 확실한 방법이다.",
