    "explanation": "**[풀이]**\n\n**기본 개념:** $2 \\times n$ 도미노 타일링의 방법 수는 피보나치 수열을 따릅니다: $a_n = a_{n-1} + a_{n-2}$\n\n**Step 1. 순차 계산**\n$a_1=1, a_2=2, a_3=3, a_4=5, a_5=8, a_6=13$\n\n**∴ 답: 13**\n\n**💡 포인트:** 도미노 타일링은 피보나치와 같은 구조이다.\n\n**[개념 정리]** 수열의 실생활 활용 유형을 정리한다.\n\n(1) **등차 활용:** 좌석 수, 급여 인상, 일정 간격 변화 (일정량 증감)\n(2) **등비 활용:** 복리, 감가상각, 세균 번식, 약물 분해 (일정비율 변화)\n(3) **무한등비급수:** 프랙탈 도형의 넓이/둘레, 반복 반사, 공 반발 거리\n(4) **연금/적립:** $A \\cdot \\frac{(1+r)^n-1}{r}$ (매기 말 적립), 여기에 $(1+r)$을 곱하면 매기 초 적립\n(5) **피보나치:** 도미노 타일링, 계단 오르기 문제\n\n실생활 문제에서는 '매번 같은 양만큼'은 등차, '매번 같은 비율만큼'은 등비로 모델링한다. 단위와 경계 조건(이상/초과, 처음/끝)에 특히 주의한다.\n\n**[풀이 전략]** 이 문제를 수능 시험장에서 만났을 때는 다음 순서로 접근한다. 먼저 주어진 조건에서 핵심 정보(첫째항, 공차/공비, 부분합 등)를 추출한다. 다음으로 적절한 공식이나 기법을 선택한다. 마지막으로 계산을 수행하고, 반드시 답을 원래 조건에 대입하여 검산한다. 검산은 실수를 방지하는 가장 확실한 방법이다.",
