    "explanation": "**[풀이]**\n\n**기본 개념:** 조건부 점화식에서 주기성을 탐색한다.\n\n**Step 1. 순차 계산**\n$2 \\to 1 \\to 4 \\to 2 \\to 1 \\to 4 \\to \\cdots$ 주기 3\n\n**Step 2. $a_{10}$**\n$10 = 3 \\times 3 + 1$이므로 $a_{10} = a_1 = 2$\n\n**∴ 답: 2**\n\n**💡 포인트:** 조건부 점화식은 주기를 찾아 나머지 연산으로 풉니다.\n\n**[개념 정리]** 킬러 문항의 주요 유형과 전략을 정리한다.\n\n(1) **바닥함수/절댓값 + 수열:** 구간별로 나누어 합산한다. $\\\\lfloor \\sqrt{k} \\\\rfloor = m$인 범위를 파악한다.\n(2) **조건부 점화식:** 몇 항을 계산하여 주기성을 탐색한다.\n(3) **$S_n$과 $a_n$의 복합 관계:** $a_n = S_n - S_{n-1}$을 대입하여 점화식을 유도한다.\n(4) **수렴하는 점화식:** 부동점 $L = f(L)$을 구하고 단조수렴정리를 적용한다.\n(5) **수론적 함수:** GCD, 분할 함수 등은 직접 계산 후 패턴을 파악한다.\n\n킬러 문항에서는 먼저 3~5개 항을 직접 계산하여 패턴을 파악한 후, 일반화 전략을 세우는 것이 효과적이다. 시간이 부족하면 선지 대입법도 유용한다.\n\n**[풀이 전략]** 이 문제를 수능 시험장에서 만났을 때는 다음 순서로 접근한다. 먼저 주어진 조건에서 핵심 정보(첫째항, 공차/공비, 부분합 등)를 추출한다. 다음으로 적절한 공식이나 기법을 선택한다. 마지막으로 계산을 수행하고, 반드시 답을 원래 조건에 대입하여 검산한다. 검산은 실수를 방지하는 가장 확실한 방법이다.",
