    "problem": "양의 실수 수열 $\\\\{a_n\\\\}$이 $a_1 = 1$, $a_{n+1} = \\sqrt{2 + a_n}$으로 정의될 때, $\\\\lim_{n \\\\to \\\\infty} a_n$의 값은?",
