    "explanation": "**[풀이]**\n\n**기본 개념:** 이차 점화식에서 양의 근만 선택한다.\n\n**Step 1. 이차방정식**\n$a_{n+1}^2 - a_n a_{n+1} - 2a_n^2 = 0$\n$a_{n+1} = \\frac{a_n \\pm 3a_n}{2}$\n$a_{n+1} = 2a_n$ ($a_n > 0$)\n\n**Step 2. 일반항**\n$a_n = 2 \\cdot 2^{n-1} = 2^n$\n①과 ②는 같은 식.\n\n**∴ 답: ⑤ ①과 ②는 같은 식**\n\n③④는 다른 수열이다.\n\n**💡 포인트:** 이차 점화식의 양의 근을 선택하면 등비수열이 된다.\n\n**[개념 정리]** 킬러 문항의 주요 유형과 전략을 정리한다.\n\n(1) **바닥함수/절댓값 + 수열:** 구간별로 나누어 합산한다. $\\\\lfloor \\sqrt{k} \\\\rfloor = m$인 범위를 파악한다.\n(2) **조건부 점화식:** 몇 항을 계산하여 주기성을 탐색한다.\n(3) **$S_n$과 $a_n$의 복합 관계:** $a_n = S_n - S_{n-1}$을 대입하여 점화식을 유도한다.\n(4) **수렴하는 점화식:** 부동점 $L = f(L)$을 구하고 단조수렴정리를 적용한다.\n(5) **수론적 함수:** GCD, 분할 함수 등은 직접 계산 후 패턴을 파악한다.\n\n킬러 문항에서는 먼저 3~5개 항을 직접 계산하여 패턴을 파악한 후, 일반화 전략을 세우는 것이 효과적이다. 시간이 부족하면 선지 대입법도 유용한다.",
